 58 │ /** Drops every `filter` and `diff` assignment (and unset/unspecify forms) from .gitattributes text, macros included. */
 59 │ export function withoutDrivers(text: string): string {
 60 │   return text.split("\n").map((line) => {
 61 │     const trimmed = line.trim();
 62 │     if (!trimmed || trimmed.startsWith("#")) return line;
