163 │   });
164 │   if (!sources.length) return undefined;
165 │   const objects = path.join(scratch, "attr-objects");
166 │   fs.mkdirSync(objects);
167 │   const env = { ...safeGitEnv(path.join(scratch, "attr-index")), GIT_OBJECT_DIRECTORY: objects };
